def _build_messages(self, messages, execute_tool=None):
    """Prepend a tool-use reminder to the system prompt when a tool is available."""
    if execute_tool is not None:
        # Prepend a concise instruction to use the provided tools for calculations and file operations.
        tool_hint = (
            "You have access to tools for arithmetic and file operations. "
            "When a task requires calculation or file creation, use the appropriate tool "
            "and report the verified result. Do not guess or fabricate results."
        )
        if messages and messages[0].get('role') == 'system':
            messages[0]['content'] = tool_hint + "\n\n" + messages[0]['content']
        else:
            messages.insert(0, {'role': 'system', 'content': tool_hint})
